(function(){'use strict';const L=(z,e)=>RWI18n.lang==='en'?e:z,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mount(){const releases=window.RW_RELEASES||[];document.querySelector('#main').innerHTML=`<div class="section-wrap"><div class="eyebrow">CREATE ANYWHERE / WEB + WINDOWS + ANDROID</div><h1>${L('在网页里开始，也能下载后继续','Start on the web, keep creating on your device')}</h1><p class="heading-sub">${L('选择适合自己的创作方式，工程可以导出备份，也可以带到另一台设备继续','Choose where to create, export projects for backup or move them to another device')}</p><div class="app-choice-grid"><article class="settings-card"><div class="eyebrow">WEB</div><h2>${L('网页创作','Create on the web')}</h2><p>${L('打开浏览器就能使用，无需安装，教程和工具随网站更新','Open your browser without installing, tools and courses update with the site')}</p><a class="btn btn-dark" href="#editors">${L('进入创作工具','Open creative tools')}</a></article>${releases.map(r=>`<article class="settings-card"><div class="eyebrow">${E(r.platform)}</div><h2>${E(r.name)}</h2><p>${L(r.descriptionZh,r.descriptionEn)}</p><p>${E(r.requirements)} · v${E(r.version)} · ${(r.size/1048576).toFixed(1)} MB</p><a class="btn btn-orange" href="${E(r.url)}">${L('下载','Download')} ${E(r.extension)} ↓</a><details><summary>${L('文件校验值','File checksum')}</summary><code style="word-break:break-all;font-size:11px">SHA-256 ${E(r.sha256)}</code></details></article>`).join('')}</div><div class="settings-card"><h2>${L('离线能做什么','What works offline?')}</h2><p>${L('下载版自带单位模组、地图触发器、单位图片和地图图片编辑器，也带有教程与参考资料，断网时可以编辑、保存工程、导入和导出文件','The downloads include unit, trigger, sprite and terrain editors, with courses and reference data, edit, save projects and import or export files without a connection')}</p><p>${L('切换到「联网 AI」后，才会连接免费问答和绘图服务，AI 功能需要可用网络及相应密钥，模型始终在云端运行','Switch to Online AI to connect the free chat and art services, cloud AI needs connectivity and the relevant API key, models stay in the cloud')}</p></div><div class="settings-card"><h2>${L('从网页搬到下载版','Move from web to app')}</h2><ol><li>${L('在当前编辑器中导出项目文件','Export your project from the current editor')}</li><li>${L('打开电脑或安卓版对应的工作台','Open the matching workbench in the Windows or Android app')}</li><li>${L('导入项目，继续修改，记得定期备份','Import and continue editing, keep regular backups')}</li></ol><p>${L('网页与下载版各自保存本地草稿，不会自动共享未导出的项目','Web and app drafts are saved separately, use a project export to transfer them')}</p></div><p><a href="https://download.noaushio.uk/" target="_blank" rel="noopener">${L('打开完整下载站 ↗','Open the download center ↗')}</a></p></div>`}
window.RWApps={mount};})();
